      /* (2162) grant_as_role_tail ::= */ yytestcase(yyruleno==2162);
      /* (2169) revoke_ignore_unknown_tail ::= */ yytestcase(yyruleno==2169);
      /* (2217) resignal_tail ::= */ yytestcase(yyruleno==2217);
      /* (2220) while_condition_tail ::= */ yytestcase(yyruleno==2220);
      /* (2222) while_condition_nested ::= */ yytestcase(yyruleno==2222);
      /* (2300) end_tail ::= */ yytestcase(yyruleno==2300);
      /* (2307) end_label_tail ::= */ yytestcase(yyruleno==2307);
      /* (2309) statement_tail ::= */ yytestcase(yyruleno==2309);
        break;
